    def tree(n, shape, lo, hi):
        vals = [rng.randint(lo, hi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if shape == 'left':
            for i in range(1, n):
                L[i - 1] = i
        elif shape == 'right':
            for i in range(1, n):
                R[i - 1] = i
        elif shape == 'zig':
            for i in range(1, n):
                if i % 2:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif shape == 'complete':
            for i in range(1, n):
                p = (i - 1) // 2
                if i % 2:
                    L[p] = i
                else:
                    R[p] = i
        else:
            if shape == 'rootR':
                slots = [(0, 1)]
            else:
